// === Tab: mySketch ===
var rects = []

async function keyPressed(){
	if(key=='r'||key=='R'){
		background(255);
		setup()
	}
}

async function setup() {
	const canvaSize = max(windowWidth, windowHeight)
	createCanvas(canvaSize, canvaSize);
	rects = []
	background(255);
	divide(0, 0, width, height, 8)

	const sameDirection = random([0.25,1])
	for(let r of rects){
		push()
		if(random()<sameDirection){
			translate(r.x, r.y)
			ktRect(0, 0, r.w, r.h ,r.tX, r.tY)
		}else if(random()<0.5){
			translate(r.x+r.w, r.y)
			scale(-1,1)
			ktRect(0, 0, r.w, r.h ,r.tX, r.tY)
		}else if(random()<0.75){
			translate(r.x, r.y+r.h)
			scale(1,-1)
			ktRect(0, 0, r.w, r.h ,r.tX, r.tY)
		}else{
			translate(r.x+r.w, r.y+r.h)
			scale(-1,-1)
			ktRect(0, 0, r.w, r.h ,r.tX, r.tY)
		}
		pop()
		await sleep(10)
	}
}

function ktRect(x, y, w, h, tX, tY){
	for(let i=0;i<w*h*0.3;i++){
		const pX = x + w*pow(random(0,pow(1,tX)),1/tX)
		const pY = y + h*pow(random(0,pow(1,tY)),1/tY)
		strokeWeight(random(0.5,1.5))
		point(pX,pY)
	}
}

function draw() {
}

function divide(x, y, w, h, step) {
	if(step == 0 || (random()<0.3 && step<5)){
		rects.push({
			x: x,
			y: y,
			w: w,
			h: h,
			tX: random(1,3),
			tY: random(1,3)
		})
		return
	}
	const ratio = random(0.2, 0.8)
	if(w*random(0.6,1.4)>h){
		divide(x, y, w*ratio, h, step-1)
		divide(x + w*ratio, y, w*(1-ratio), h, step-1)
	}else{
		divide(x, y, w, h*ratio, step-1)
		divide(x, y + h*ratio, w, h*(1-ratio), step-1)
	}
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms))
}
